import winston from "winston";
import path from "node:path";
import fs from "node:fs";
import util from "node:util";
import { pipeline } from "node:stream/promises";
import { createGzip } from "node:zlib";
import DailyRotateFile from "winston-daily-rotate-file";

const { combine, timestamp, printf, colorize } = winston.format;

/**
 * Available log levels in order of severity.
 *
 * @typedef {'silly' | 'debug' | 'verbose' | 'info' | 'warn' | 'error' | 'critical'} LogLevel
 */

/**
 * Logger rotation configuration.
 *
 * @typedef {Object} RotationConfig
 * @property {string} [datePattern="YYYY-MM-DD"] Date pattern used for rotation.
 * @property {string|null} [frequency=null] Optional rotation frequency.
 * @property {string} [maxSize="20m"] Maximum active log file size.
 * @property {number} [retentionDays=14] Archive retention period in days.
 * @property {number} [cleanupIntervalHours=6] Archive cleanup interval.
 */

/**
 * Logger configuration options.
 *
 * @typedef {Object} LoggerConfig
 * @property {string} label Logger label or context.
 * @property {LogLevel} [logLevel="silly"] Minimum log level.
 * @property {string} [logFile="application"] Base log filename.
 * @property {string} [logDir="logs"] Active log directory.
 * @property {string} [archiveDir] Separate archive directory.
 * @property {RotationConfig} [rotation] Rotation configuration.
 * @property {string} [env="production"] Application environment.
 */

/**
 * Logger method signature.
 *
 * @callback LoggerMethod
 * @param {*} [message] Primary log message.
 * @param {...*} args Additional log arguments.
 * @returns {void}
 */

/**
 * Logger instance.
 *
 * @typedef {Object} LoggerInstance
 * @property {LoggerMethod} error
 * @property {LoggerMethod} warn
 * @property {LoggerMethod} info
 * @property {LoggerMethod} debug
 * @property {LoggerMethod} critical
 * @property {LoggerMethod} verbose
 * @property {LoggerMethod} silly
 */

/**
 * Custom Winston log levels.
 */
const customLevels = {
  levels: {
    error: 0,
    warn: 1,
    info: 2,
    verbose: 3,
    debug: 4,
    silly: 5,
    critical: 0,
  },
  colors: {
    error: "red",
    warn: "yellow",
    info: "green",
    verbose: "cyan",
    debug: "blue",
    silly: "magenta",
    critical: "red bold",
  },
};

winston.addColors(customLevels.colors);

/**
 * Utility to retry an asynchronous operation.
 *
 * @param {Function} fn The async function to execute.
 * @param {number} [retries=3] Number of retry attempts.
 * @param {number} [delay=2000] Delay in milliseconds between retries.
 * @param {Object} [logger] Logger instance to use for retry logs.
 * @returns {Promise<any>}
 */
const retryWithDelay = async (fn, retries = 3, delay = 2000, logger = null) => {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      if (attempt === retries) throw error;

      const msg = `Attempt ${attempt} failed. Retrying in ${delay}ms... (${error.message})`;
      if (logger) logger.warn(msg);
      else console.warn(msg);

      await new Promise((res) => setTimeout(res, delay));
    }
  }
};

/**
 * Get the caller's source location.
 *
 * @param {number} [skipFrames=3] Number of stack frames to skip.
 * @returns {string} Caller location.
 */
const getCallerLocation = (skipFrames = 3) => {
  try {
    const err = new Error();
    const stack = err.stack || "";
    const lines = stack.split("\n");
    const startIndex = skipFrames + 1;

    for (let i = startIndex; i < lines.length; i++) {
      const line = lines[i];

      if (
        line.includes("node_modules") ||
        line.includes("internal/") ||
        line.includes("module_job") ||
        line.includes("run_main")
      ) {
        continue;
      }

      const match =
        line.match(/\((.*):(\d+):(\d+)\)/) || line.match(/at (.*):(\d+):(\d+)/);

      if (match) {
        let filePath = match[1];
        const lineNumber = match[2];
        const columnNumber = match[3];

        if (filePath.startsWith("file://")) {
          filePath = filePath.substring(7);
        }

        const fileName = path.basename(filePath);

        return `${fileName}:${lineNumber}:${columnNumber}`;
      }
    }

    return "unknown:0:0";
  } catch {
    return "unknown:0:0";
  }
};

/**
 * Format a value for logging.
 *
 * @param {*} value Value to format.
 * @returns {string} Formatted value.
 */
const formatValue = (value) => {
  if (value === null) return "null";
  if (value === undefined) return "undefined";
  if (typeof value === "string") return value;

  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }

  if (value instanceof Error) {
    return `[Error: ${value.message}]`;
  }

  return util.inspect(value, {
    showHidden: false,
    depth: 3,
    colors: false,
    compact: false,
    breakLength: 80,
  });
};

/**
 * Process log arguments and extract metadata.
 *
 * @param {*} message Primary message.
 * @param {Array<*>} args Additional arguments.
 * @returns {{message: string, meta: Object}} Processed log data.
 */
const processLogArgs = (message, args) => {
  let formattedMessage = "";
  const meta = {};
  const extraParts = [];

  if (
    message &&
    typeof message === "object" &&
    !(message instanceof Error) &&
    args.length === 0
  ) {
    return {
      message: formatValue(message),
      meta: {},
    };
  }

  if (message && typeof message === "object" && !(message instanceof Error)) {
    formattedMessage = formatValue(message);
  } else if (
    typeof message === "string" ||
    typeof message === "number" ||
    typeof message === "boolean"
  ) {
    formattedMessage = String(message);
  } else if (message instanceof Error) {
    formattedMessage = message.message;
    meta.error = formatErrorForLogs(message);
  } else {
    formattedMessage = "No message provided";
  }

  args.forEach((arg) => {
    if (arg === null) {
      extraParts.push("null");
    } else if (arg === undefined) {
      extraParts.push("undefined");
    } else if (
      typeof arg === "string" ||
      typeof arg === "number" ||
      typeof arg === "boolean"
    ) {
      extraParts.push(String(arg));
    } else if (arg instanceof Error) {
      meta.error = formatErrorForLogs(arg);
      extraParts.push(`[Error: ${arg.message}]`);
    } else if (typeof arg === "object") {
      Object.assign(meta, arg);

      if (
        message &&
        typeof message === "object" &&
        !(message instanceof Error)
      ) {
        extraParts.push(formatValue(arg));
      }
    } else {
      extraParts.push(String(arg));
    }
  });

  if (extraParts.length > 0) {
    formattedMessage += ` ${extraParts.join(" ")}`;
  }

  return {
    message: formattedMessage,
    meta,
  };
};

/**
 * Format error objects for structured logging.
 *
 * @param {*} error Error to format.
 * @returns {Object} Formatted error object.
 */
export const formatErrorForLogs = (error) => {
  if (error instanceof Error) {
    return {
      name: error.name,
      message: error.message,
      stack: error.stack,
      ...(error.code ? { code: error.code } : {}),
    };
  }

  return { rawError: error };
};

/**
 * Format log metadata.
 *
 * @param {Object} meta Log metadata.
 * @param {boolean} colors Enable terminal colors.
 * @returns {string} Formatted metadata.
 */
const formatMeta = (meta, colors = false) => {
  const filteredMeta = {};

  Object.keys(meta).forEach((key) => {
    if (key !== "label" && key !== "location" && key !== "timestamp") {
      filteredMeta[key] = meta[key];
    }
  });

  if (Object.keys(filteredMeta).length === 0) {
    return "";
  }

  return (
    " " +
    util.inspect(filteredMeta, {
      showHidden: false,
      depth: 3,
      colors,
      compact: false,
      breakLength: 80,
    })
  );
};

/**
 * Console log format with colorization.
 */
const consoleFormat = combine(
  colorize(),
  timestamp({ format: "YYYY-MM-DD HH:mm:ss" }),
  printf(
    ({ level, message, label, timestamp: logTimestamp, location, ...meta }) => {
      const locationStr = location ? ` \x1b[90m(${location})\x1b[0m` : "";

      return (
        `${logTimestamp} [${label}] ${level}: ${message}` +
        formatMeta(meta, true) +
        locationStr
      );
    },
  ),
);

/**
 * File log format without terminal colors.
 */
const fileFormat = combine(
  timestamp({ format: "YYYY-MM-DD HH:mm:ss" }),
  printf(
    ({ level, message, label, timestamp: logTimestamp, location, ...meta }) => {
      const locationStr = location ? ` (${location})` : "";

      return (
        `${logTimestamp} [${label}] ${level}: ${message}` +
        formatMeta(meta, false) +
        locationStr
      );
    },
  ),
);

/**
 * Ensure that a directory exists.
 *
 * @param {string} directory Directory path.
 * @returns {void}
 * @throws {Error} If directory creation fails.
 */
const ensureLogDirectory = (directory) => {
  try {
    fs.mkdirSync(directory, { recursive: true });
  } catch (error) {
    console.error(`Failed to create directory: ${directory}`, error);

    throw error;
  }
};

/**
 * Check whether a filename belongs to the configured logger.
 *
 * @param {string} filename Filename to check.
 * @param {string} logFile Base log filename.
 * @returns {boolean} Whether the file matches.
 */
const isLoggerFile = (filename, logFile) => {
  return (
    filename.startsWith(`${logFile}-`) &&
    /\.log(?:\.\d+)?(?:\.gz)?$/.test(filename)
  );
};

/**
 * Create a temporary archive filename.
 *
 * @param {string} archiveDir Archive directory.
 * @param {string} filename Original filename.
 * @returns {string} Temporary archive path.
 */
const createTemporaryArchivePath = (archiveDir, filename) => {
  return path.join(archiveDir, `.${filename}.${process.pid}.${Date.now()}.tmp`);
};

/**
 * Moves a file safely to the archive directory.
 * If the file is already a .gz, it moves it directly.
 * If it is a .log, it compresses it and then moves it.
 * Retries up to 3 times on failure.
 *
 * @param {string} sourcePath Source log file.
 * @param {string} archiveDir Archive directory.
 * @param {Object} logger Logger instance for logging operations.
 * @returns {Promise<boolean>} Whether archiving succeeded.
 */
const archiveLogFile = async (sourcePath, archiveDir, logger) => {
  const filename = path.basename(sourcePath);
  const isGzip = filename.endsWith(".gz");

  // If it's already gz, the target name is the same.
  // If it's a .log, the target name will be .log.gz
  const targetFilename = isGzip ? filename : `${filename}.gz`;
  const archivePath = path.join(archiveDir, targetFilename);

  try {
    const sourceStats = await fs.promises.stat(sourcePath);
    if (!sourceStats.isFile()) return false;

    // Check if target already exists
    try {
      await fs.promises.access(archivePath);
      logger.warn(`Archive already exists, skipping: ${archivePath}`);
      return false;
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
    }

    if (isGzip) {
      // Just move the file directly with retries
      await retryWithDelay(
        async () => {
          await fs.promises.rename(sourcePath, archivePath);
        },
        3,
        2000,
        logger,
      );

      logger.info(`Moved gz archive: ${archivePath}`);
      return true;
    } else {
      // Compress and move with retries
      await retryWithDelay(
        async () => {
          const temporaryPath = createTemporaryArchivePath(
            archiveDir,
            filename,
          );

          await pipeline(
            fs.createReadStream(sourcePath),
            createGzip(),
            fs.createWriteStream(temporaryPath, { flags: "wx" }),
          );

          const compressedStats = await fs.promises.stat(temporaryPath);
          if (compressedStats.size === 0) {
            throw new Error(`Compressed archive is empty: ${temporaryPath}`);
          }

          // Link (atomic move) to final destination
          await fs.promises.link(temporaryPath, archivePath);
          await fs.promises.unlink(temporaryPath);

          // Delete original
          await fs.promises.unlink(sourcePath);
        },
        3,
        2000,
        logger,
      );

      logger.info(`Log archived successfully: ${archivePath}`);
      return true;
    }
  } catch (error) {
    logger.error(
      `Failed to archive log file after 3 retries: ${sourcePath}`,
      error,
    );

    // Cleanup temporary file if exists
    const temporaryPath = createTemporaryArchivePath(archiveDir, filename);
    try {
      await fs.promises.unlink(temporaryPath);
    } catch (e) {
      /* ignore */
    }

    return false;
  }
};

/**
 * Delete archived log files older than the retention period.
 *
 * Only matching compressed log files are deleted.
 *
 * @param {string} archiveDir Archive directory.
 * @param {string} logFile Base log filename.
 * @param {number} retentionDays Retention period in days.
 * @param {Object} logger Logger instance for logging operations.
 * @returns {Promise<void>}
 */
const cleanupArchivedLogs = async (
  archiveDir,
  logFile,
  retentionDays = 14,
  logger,
) => {
  const cutoff = Date.now() - retentionDays * 24 * 60 * 60 * 1000;

  try {
    const entries = await fs.promises.readdir(archiveDir, {
      withFileTypes: true,
    });

    for (const entry of entries) {
      if (!entry.isFile()) {
        continue;
      }

      if (
        !entry.name.startsWith(`${logFile}-`) ||
        !/\.log(?:\.\d+)?(?:\.gz)?$/.test(entry.name)
      ) {
        continue;
      }

      const filePath = path.join(archiveDir, entry.name);

      try {
        const stats = await fs.promises.stat(filePath);

        if (stats.mtimeMs < cutoff) {
          await fs.promises.unlink(filePath);

          logger.info(`Expired log archive removed: ${filePath}`);
        }
      } catch (error) {
        logger.error(`Failed to inspect or remove archive: ${filePath}`, error);
      }
    }
  } catch (error) {
    logger.error(`Failed to clean archive directory: ${archiveDir}`, error);
  }
};

/**
 * Recover rotated log files left in the active log directory.
 *
 * Files are archived only when they are not the currently
 * active transport file and are old enough to avoid
 * archiving a file still being written.
 *
 * @param {string} logDir Active log directory.
 * @param {string} archiveDir Archive directory.
 * @param {string} logFile Base log filename.
 * @param {Function} getActiveFilename Active filename resolver.
 * @param {number} [minimumAgeMs=60000] Minimum file age.
 * @param {Object} logger Logger instance for logging operations.
 * @returns {Promise<void>}
 */
const recoverRotatedLogs = async (
  logDir,
  archiveDir,
  logFile,
  getActiveFilename,
  minimumAgeMs = 60000,
  logger,
) => {
  try {
    const entries = await fs.promises.readdir(logDir, { withFileTypes: true });

    const activeFilename = getActiveFilename();

    for (const entry of entries) {
      if (!entry.isFile()) {
        continue;
      }

      if (!isLoggerFile(entry.name, logFile)) {
        continue;
      }

      // Skip the active file
      if (
        activeFilename &&
        path.resolve(path.join(logDir, entry.name)) ===
          path.resolve(activeFilename)
      ) {
        continue;
      }

      const filePath = path.join(logDir, entry.name);

      try {
        const stats = await fs.promises.stat(filePath);

        if (Date.now() - stats.mtimeMs < minimumAgeMs) {
          continue;
        }

        // Calls the updated archiveLogFile that handles both .log and .gz
        await archiveLogFile(filePath, archiveDir, logger);
      } catch (error) {
        logger.error(`Failed to recover log file: ${filePath}`, error);
      }
    }
  } catch (error) {
    logger.error(`Failed to recover rotated logs: ${logDir}`, error);
  }
};

/**
 * Create a logger instance with automatic caller tracking,
 * log rotation, compression, archiving, and retention.
 *
 * Active log files are stored in logDir.
 * Rotated log files are compressed into archiveDir.
 *
 * @param {LoggerConfig} config Logger configuration.
 * @returns {LoggerInstance} Logger instance.
 */
export const createLogger = ({
  label,
  logLevel = "silly",
  logFile = "application",
  logDir = "logs",
  archiveDir,
  rotation = {},
  env = "production",
}) => {
  ensureLogDirectory(logDir);

  if (archiveDir) {
    ensureLogDirectory(archiveDir);

    if (path.resolve(logDir) === path.resolve(archiveDir)) {
      throw new Error("archiveDir must be different from logDir");
    }
  }

  const retentionDays = rotation.retentionDays ?? 14;

  const cleanupIntervalHours = rotation.cleanupIntervalHours ?? 6;

  if (!Number.isFinite(retentionDays) || retentionDays <= 0) {
    throw new Error("rotation.retentionDays must be greater than zero");
  }

  if (!Number.isFinite(cleanupIntervalHours) || cleanupIntervalHours <= 0) {
    throw new Error("rotation.cleanupIntervalHours must be greater than zero");
  }

  const filename = `${logFile}-%DATE%.log`;

  const fileTransport = new DailyRotateFile({
    dirname: logDir,
    filename,
    datePattern: rotation.datePattern ?? "YYYY-MM-DD",

    // Date-based rotation is used by default.
    frequency: rotation.frequency ?? null,

    // Rotate when the active file reaches the size limit.
    maxSize: rotation.maxSize ?? "20m",

    // Archive management is handled separately.
    maxFiles: archiveDir ? null : (rotation.maxFiles ?? "14d"),

    // WE FORCE THIS TO FALSE. We handle zipping manually to avoid conflicts.
    zippedArchive: false,

    format: fileFormat,
  });

  const baseLogger = winston.createLogger({
    levels: customLevels.levels,
    level: logLevel,
    transports: [
      ...(env === "development"
        ? [
            new winston.transports.Console({
              format: consoleFormat,
            }),
          ]
        : []),
      fileTransport,
    ],
    defaultMeta: { label },
  });

  // Dedicated logger for archive operations with a distinct label
  // const archiveLogger = baseLogger.child({
  //   label: "📦 Log-Archiver",
  // });

  const ARCHIVE_LABEL = "📦 Log-Archiver";

  const archiveLogger = {
    error: (msg, ...a) =>
      baseLogger.log("error", msg, { label: ARCHIVE_LABEL, ...a }),
    warn: (msg, ...a) =>
      baseLogger.log("warn", msg, { label: ARCHIVE_LABEL, ...a }),
    info: (msg, ...a) =>
      baseLogger.log("info", msg, { label: ARCHIVE_LABEL, ...a }),
    debug: (msg, ...a) =>
      baseLogger.log("debug", msg, { label: ARCHIVE_LABEL, ...a }),
  };

  archiveLogger.info(
    "📦 Log-Archiver initialized successfully........... ******************* ",
  );
  // console.log("initialized successfully........... ******************* ")

  fileTransport.on("error", (error) => {
    baseLogger.error("Winston file transport error:", error);
  });

  if (archiveDir) {
    let archiveQueue = Promise.resolve();

    /**
     * Queue archive operations to prevent overlapping
     * archive and cleanup tasks within this logger instance.
     *
     * @param {Function} task Asynchronous archive task.
     * @returns {void}
     */
    const enqueueArchiveTask = (task) => {
      archiveQueue = archiveQueue.then(task).catch((error) => {
        archiveLogger.error("Archive queue task failed:", error);
      });
    };

    /**
     * Resolve the currently active transport filename.
     *
     * @returns {string|null} Active filename.
     */
    const getActiveFilename = () => {
      return fileTransport._stream?.filename ?? null;
    };

    /**
     * Run archive recovery and retention cleanup.
     *
     * @returns {Promise<void>}
     */
    const performMaintenance = async () => {
      await recoverRotatedLogs(
        logDir,
        archiveDir,
        logFile,
        getActiveFilename,
        60000,
        archiveLogger,
      );

      await cleanupArchivedLogs(
        archiveDir,
        logFile,
        retentionDays,
        archiveLogger,
      );
    };

    fileTransport.on("rotate", (oldFilename, newFilename) => {
      enqueueArchiveTask(async () => {
        archiveLogger.info("Log rotation detected:", {
          oldFilename,
          newFilename,
        });

        const archived = await archiveLogFile(
          oldFilename,
          archiveDir,
          archiveLogger,
        );

        if (archived) {
          await cleanupArchivedLogs(
            archiveDir,
            logFile,
            retentionDays,
            archiveLogger,
          );
        }
      });
    });

    // Recover old files and remove expired archives on startup.
    enqueueArchiveTask(performMaintenance);

    // Periodically retry recovery and retention cleanup.
    const maintenanceTimer = setInterval(
      () => {
        enqueueArchiveTask(performMaintenance);
      },
      cleanupIntervalHours * 60 * 60 * 1000,
    );

    // Do not keep Node.js running only for archive maintenance.
    maintenanceTimer.unref();
  }

  /**
   * Create a logger method with automatic caller tracking.
   *
   * @param {LogLevel} level Winston log level.
   * @returns {LoggerMethod} Logger method.
   */
  const createLogMethod = (level) => {
    return (message, ...args) => {
      const location = getCallerLocation(2);

      const { message: formattedMessage, meta } = processLogArgs(message, args);

      baseLogger.log(level, formattedMessage, {
        ...meta,
        location,
      });
    };
  };

  return {
    error: createLogMethod("error"),
    warn: createLogMethod("warn"),
    info: createLogMethod("info"),
    debug: createLogMethod("debug"),
    critical: createLogMethod("critical"),
    verbose: createLogMethod("verbose"),
    silly: createLogMethod("silly"),
  };
};

/**
 * Default export for the logger factory.
 *
 * @module logger
 * @exports {Function} createLogger
 */
export default createLogger;
